import React, { useState, useEffect } from 'react';
import {
    Box,
    Typography,
    TextField,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Snackbar,
    Grid,
    Paper,
    Card,
    CardContent,
    IconButton,
    Chip,
    Grow,
    alpha,
    useTheme,
    Divider,
    Tooltip,
    Stack,
    Container,
} from '@mui/material';
import {
    Add,
    Search,
    Edit,
    Delete,
    Inventory,
    AttachMoney,
    Store,
    Warning,
    CheckCircle,
    Cancel,
    Save,
    Close,
    Category,
    Numbers,
    LocalOffer,
    Assessment,
    Refresh,
} from '@mui/icons-material';
import { ref, get, set, remove, push } from 'firebase/database';
import { db } from './firebaseConfig';
import { useNavigate } from 'react-router-dom';
import lumarfoto from './lumar.png';

function Stock() {
    console.log('🟢 Componente Stock montado');
    const theme = useTheme();
    const navigate = useNavigate();

    // ===== STATES =====
    const [productos, setProductos] = useState([]);
    const [filtro, setFiltro] = useState('');
    const [nombre, setNombre] = useState('');
    const [stock, setStock] = useState('');
    const [precioCompra, setPrecioCompra] = useState('');
    const [precioVenta, setPrecioVenta] = useState('');
    const [stockMinimo, setStockMinimo] = useState('');
    const [productoSeleccionado, setProductoSeleccionado] = useState(null);
    const [alertaStock, setAlertaStock] = useState(false);
    const [mensajeAlerta, setMensajeAlerta] = useState('');
    const [productosConAlerta, setProductosConAlerta] = useState([]);
    const [tipoAlerta, setTipoAlerta] = useState('error');
    const [guardando, setGuardando] = useState(false);
    const [cargando, setCargando] = useState(true);
    const [dialogoEditar, setDialogoEditar] = useState(false);

    // ===== FUNCIONES =====
    const cargarProductos = async () => {
        setCargando(true);
        try {
            const productosRef = ref(db, 'productos');
            const productosSnapshot = await get(productosRef);
            const productosData = productosSnapshot.exists() ? productosSnapshot.val() : {};
            const productosConId = Object.entries(productosData).map(([key, value]) => ({ id: key, ...value }));
            setProductos(productosConId);
            verificarStockBajo(productosConId);
        } catch (error) {
            console.error('❌ Error cargando productos:', error);
            setTipoAlerta('error');
            setMensajeAlerta('❌ Error al cargar productos');
            setAlertaStock(true);
        } finally {
            setCargando(false);
        }
    };

    useEffect(() => {
        cargarProductos();
    }, []);

    const mostrarSnackbar = (mensaje, tipo = 'success') => {
        setTipoAlerta(tipo);
        setMensajeAlerta(mensaje);
        setAlertaStock(true);
    };

    const guardarProducto = async () => {
        console.log('🟡 === INICIO guardarProducto ===');
        console.log('📝 Valores del formulario:', { nombre, stock, precioCompra, precioVenta, stockMinimo });

        setGuardando(true);

        // ===== VALIDACIONES =====
        if (!nombre || nombre.trim() === '') {
            mostrarSnackbar('⚠️ El nombre del producto es obligatorio', 'error');
            setGuardando(false);
            return;
        }

        const stockNum = Number(stock);
        const precioCompraNum = Number(precioCompra);
        const precioVentaNum = Number(precioVenta);
        const stockMinimoNum = Number(stockMinimo);

        if (isNaN(stockNum) || stockNum < 0) {
            mostrarSnackbar('⚠️ El stock debe ser un número mayor o igual a 0', 'error');
            setGuardando(false);
            return;
        }

        if (isNaN(precioCompraNum) || precioCompraNum < 0) {
            mostrarSnackbar('⚠️ El precio de compra debe ser un número mayor o igual a 0', 'error');
            setGuardando(false);
            return;
        }

        if (isNaN(precioVentaNum) || precioVentaNum < 0) {
            mostrarSnackbar('⚠️ El precio de venta debe ser un número mayor o igual a 0', 'error');
            setGuardando(false);
            return;
        }

        if (isNaN(stockMinimoNum) || stockMinimoNum < 0) {
            mostrarSnackbar('⚠️ El stock mínimo debe ser un número mayor o igual a 0', 'error');
            setGuardando(false);
            return;
        }

        try {
            const nuevoProducto = {
                nombre: nombre.trim(),
                stock: stockNum,
                precioCompra: precioCompraNum,
                precioVenta: precioVentaNum,
                stockMinimo: stockMinimoNum,
            };

            const productosRef = ref(db, 'productos');
            const nuevoProductoRef = push(productosRef);
            await set(nuevoProductoRef, nuevoProducto);

            await cargarProductos();

            setNombre('');
            setStock('');
            setPrecioCompra('');
            setPrecioVenta('');
            setStockMinimo('');

            mostrarSnackbar(`✅ Producto "${nombre}" agregado correctamente`, 'success');
            console.log('✅ === FIN guardarProducto (EXITO) ===');

        } catch (error) {
            console.error('❌ Error al guardar:', error);
            mostrarSnackbar(`❌ Error al guardar: ${error.message}`, 'error');
        } finally {
            setGuardando(false);
        }
    };

    const eliminarProducto = async (idProducto, nombreProducto) => {
        if (window.confirm(`¿Estás seguro de eliminar "${nombreProducto}"?`)) {
            try {
                await remove(ref(db, `productos/${idProducto}`));
                await cargarProductos();
                mostrarSnackbar(`🗑️ Producto "${nombreProducto}" eliminado`, 'info');
            } catch (error) {
                mostrarSnackbar('❌ Error al eliminar producto', 'error');
            }
        }
    };

    const abrirDialogoEditar = (producto) => {
        setProductoSeleccionado(producto);
        setDialogoEditar(true);
    };

    const cerrarDialogoEditar = () => {
        setProductoSeleccionado(null);
        setDialogoEditar(false);
    };

    const guardarCambios = async () => {
        if (productoSeleccionado) {
            try {
                const { id, nombre, stock, precioCompra, precioVenta, stockMinimo } = productoSeleccionado;

                await set(ref(db, `productos/${id}`), {
                    nombre,
                    stock: Number(stock),
                    precioCompra: Number(precioCompra),
                    precioVenta: Number(precioVenta),
                    stockMinimo: Number(stockMinimo),
                });

                await cargarProductos();
                cerrarDialogoEditar();
                mostrarSnackbar(`✅ Producto "${nombre}" actualizado`, 'success');
            } catch (error) {
                mostrarSnackbar('❌ Error al actualizar producto', 'error');
            }
        }
    };

    const verificarStockBajo = (productos) => {
        const productosConStockBajo = productos.filter(
            (producto) => producto.stock <= producto.stockMinimo
        );

        productosConStockBajo.forEach((producto) => {
            if (!productosConAlerta.includes(producto.nombre)) {
                mostrarSnackbar(`⚠️ Stock bajo: ${producto.nombre} (Stock: ${producto.stock})`, 'error');
                setProductosConAlerta((prev) => [...prev, producto.nombre]);
            }
        });
    };

    const productosFiltrados = productos.filter((producto) =>
        producto.nombre?.toLowerCase().includes(filtro.toLowerCase())
    );

    // ===== ESTADÍSTICAS =====
    const totalProductos = productos.length;
    const totalStock = productos.reduce((sum, p) => sum + p.stock, 0);
    const productosBajoStock = productos.filter(p => p.stock <= p.stockMinimo).length;
    const valorInventario = productos.reduce((sum, p) => sum + (p.precioVenta * p.stock), 0);

    return (
        <Box sx={{ width: '100%' }}>
            {/* ===== HEADER ===== */}
            <Paper
                elevation={0}
                sx={{
                    p: 3,
                    borderRadius: 4,
                    background: `linear-gradient(135deg, ${alpha(theme.palette.background.paper, 0.9)} 0%, ${alpha(theme.palette.background.default, 0.5)} 100%)`,
                    border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                    boxShadow: '0 8px 32px rgba(0,0,0,0.06)',
                }}
            >
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 3, flexWrap: 'wrap', gap: 2 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                        <Box
                            component="img"
                            src={lumarfoto}
                            alt="Logo Lumar"
                            sx={{
                                width: 50,
                                height: 50,
                                borderRadius: '50%',
                                objectFit: 'contain',
                                boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                            }}
                        />
                        <Box>
                            <Typography variant="h5" sx={{ fontWeight: 700 }}>
                                Gestión de Stock
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                Administra tu inventario de productos
                            </Typography>
                        </Box>
                    </Box>

                    <Box sx={{ display: 'flex', gap: 1 }}>
                        <Tooltip title="Recargar productos">
                            <IconButton onClick={cargarProductos} sx={{ borderRadius: 2 }}>
                                <Refresh />
                            </IconButton>
                        </Tooltip>
                    </Box>
                </Box>

                {/* ===== ESTADÍSTICAS ===== */}
                <Grid container spacing={2} sx={{ mb: 3 }}>
                    <Grid item xs={6} sm={3}>
                        <Paper
                            sx={{
                                p: 2,
                                borderRadius: 3,
                                textAlign: 'center',
                                background: `linear-gradient(135deg, ${alpha(theme.palette.primary.main, 0.05)} 0%, ${alpha(theme.palette.secondary.main, 0.05)} 100%)`,
                                border: `1px solid ${alpha(theme.palette.divider, 0.08)}`,
                                transition: 'all 0.3s ease',
                                '&:hover': {
                                    transform: 'translateY(-2px)',
                                    boxShadow: '0 8px 25px rgba(0,0,0,0.06)',
                                },
                            }}
                        >
                            <Inventory sx={{ color: 'primary.main', fontSize: 28, mb: 0.5 }} />
                            <Typography variant="h6" sx={{ fontWeight: 700 }}>
                                {totalProductos}
                            </Typography>
                            <Typography variant="caption" color="textSecondary">
                                Total Productos
                            </Typography>
                        </Paper>
                    </Grid>
                    <Grid item xs={6} sm={3}>
                        <Paper
                            sx={{
                                p: 2,
                                borderRadius: 3,
                                textAlign: 'center',
                                background: `linear-gradient(135deg, ${alpha(theme.palette.info.main, 0.05)} 0%, ${alpha(theme.palette.info.light, 0.05)} 100%)`,
                                border: `1px solid ${alpha(theme.palette.divider, 0.08)}`,
                                transition: 'all 0.3s ease',
                                '&:hover': {
                                    transform: 'translateY(-2px)',
                                    boxShadow: '0 8px 25px rgba(0,0,0,0.06)',
                                },
                            }}
                        >
                            <Store sx={{ color: 'info.main', fontSize: 28, mb: 0.5 }} />
                            <Typography variant="h6" sx={{ fontWeight: 700 }}>
                                {totalStock}
                            </Typography>
                            <Typography variant="caption" color="textSecondary">
                                Stock Total
                            </Typography>
                        </Paper>
                    </Grid>
                    <Grid item xs={6} sm={3}>
                        <Paper
                            sx={{
                                p: 2,
                                borderRadius: 3,
                                textAlign: 'center',
                                background: `linear-gradient(135deg, ${alpha(theme.palette.error.main, 0.05)} 0%, ${alpha(theme.palette.error.light, 0.05)} 100%)`,
                                border: `1px solid ${alpha(theme.palette.divider, 0.08)}`,
                                transition: 'all 0.3s ease',
                                '&:hover': {
                                    transform: 'translateY(-2px)',
                                    boxShadow: '0 8px 25px rgba(0,0,0,0.06)',
                                },
                            }}
                        >
                            <Warning sx={{ color: 'error.main', fontSize: 28, mb: 0.5 }} />
                            <Typography variant="h6" sx={{ fontWeight: 700, color: 'error.main' }}>
                                {productosBajoStock}
                            </Typography>
                            <Typography variant="caption" color="textSecondary">
                                Stock Bajo
                            </Typography>
                        </Paper>
                    </Grid>
                    <Grid item xs={6} sm={3}>
                        <Paper
                            sx={{
                                p: 2,
                                borderRadius: 3,
                                textAlign: 'center',
                                background: `linear-gradient(135deg, ${alpha(theme.palette.success.main, 0.05)} 0%, ${alpha(theme.palette.success.light, 0.05)} 100%)`,
                                border: `1px solid ${alpha(theme.palette.divider, 0.08)}`,
                                transition: 'all 0.3s ease',
                                '&:hover': {
                                    transform: 'translateY(-2px)',
                                    boxShadow: '0 8px 25px rgba(0,0,0,0.06)',
                                },
                            }}
                        >
                            <Assessment sx={{ color: 'success.main', fontSize: 28, mb: 0.5 }} />
                            <Typography variant="h6" sx={{ fontWeight: 700 }}>
                                ${valorInventario.toFixed(0)}
                            </Typography>
                            <Typography variant="caption" color="textSecondary">
                                Valor Inventario
                            </Typography>
                        </Paper>
                    </Grid>
                </Grid>
            </Paper>

            {/* ===== FORMULARIO DE AGREGAR ===== */}
            <Paper
                elevation={0}
                sx={{
                    mt: 3,
                    p: 3,
                    borderRadius: 4,
                    background: `linear-gradient(135deg, ${alpha(theme.palette.background.paper, 0.9)} 0%, ${alpha(theme.palette.background.default, 0.5)} 100%)`,
                    border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                    boxShadow: '0 8px 32px rgba(0,0,0,0.06)',
                }}
            >
                <Typography variant="h6" sx={{ fontWeight: 600, mb: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Add color="primary" />
                    Agregar Nuevo Producto
                </Typography>

                <Box onKeyDown={(e) => e.key === 'Enter' && guardarProducto()}>
                    <Grid container spacing={2}>
                        <Grid item xs={12} sm={4}>
                            <TextField
                                label="Nombre"
                                fullWidth
                                value={nombre}
                                onChange={(e) => setNombre(e.target.value)}
                                sx={{
                                    '& .MuiOutlinedInput-root': {
                                        borderRadius: 2,
                                        background: alpha(theme.palette.background.paper, 0.6),
                                    },
                                }}
                                InputProps={{
                                    startAdornment: <Category sx={{ mr: 1, color: 'text.secondary', fontSize: 20 }} />,
                                }}
                            />
                        </Grid>
                        <Grid item xs={12} sm={2}>
                            <TextField
                                type="number"
                                label="Stock"
                                fullWidth
                                value={stock}
                                onChange={(e) => setStock(e.target.value)}
                                sx={{
                                    '& .MuiOutlinedInput-root': {
                                        borderRadius: 2,
                                        background: alpha(theme.palette.background.paper, 0.6),
                                    },
                                }}
                                InputProps={{
                                    startAdornment: <Numbers sx={{ mr: 1, color: 'text.secondary', fontSize: 20 }} />,
                                }}
                            />
                        </Grid>
                        <Grid item xs={12} sm={2}>
                            <TextField
                                type="number"
                                label="Precio Compra"
                                fullWidth
                                value={precioCompra}
                                onChange={(e) => setPrecioCompra(e.target.value)}
                                sx={{
                                    '& .MuiOutlinedInput-root': {
                                        borderRadius: 2,
                                        background: alpha(theme.palette.background.paper, 0.6),
                                    },
                                }}
                                InputProps={{
                                    startAdornment: <AttachMoney sx={{ mr: 1, color: 'text.secondary', fontSize: 20 }} />,
                                }}
                            />
                        </Grid>
                        <Grid item xs={12} sm={2}>
                            <TextField
                                type="number"
                                label="Precio Venta"
                                fullWidth
                                value={precioVenta}
                                onChange={(e) => setPrecioVenta(e.target.value)}
                                sx={{
                                    '& .MuiOutlinedInput-root': {
                                        borderRadius: 2,
                                        background: alpha(theme.palette.background.paper, 0.6),
                                    },
                                }}
                                InputProps={{
                                    startAdornment: <LocalOffer sx={{ mr: 1, color: 'text.secondary', fontSize: 20 }} />,
                                }}
                            />
                        </Grid>
                        <Grid item xs={12} sm={2}>
                            <TextField
                                type="number"
                                label="Stock Mínimo"
                                fullWidth
                                value={stockMinimo}
                                onChange={(e) => setStockMinimo(e.target.value)}
                                sx={{
                                    '& .MuiOutlinedInput-root': {
                                        borderRadius: 2,
                                        background: alpha(theme.palette.background.paper, 0.6),
                                    },
                                }}
                                InputProps={{
                                    startAdornment: <Warning sx={{ mr: 1, color: 'text.secondary', fontSize: 20 }} />,
                                }}
                            />
                        </Grid>
                        <Grid item xs={12}>
                            <Button
                                onClick={guardarProducto}
                                disabled={guardando}
                                variant="contained"
                                fullWidth
                                startIcon={guardando ? null : <Add />}
                                sx={{
                                    borderRadius: 2,
                                    py: 1.5,
                                    fontWeight: 600,
                                    textTransform: 'none',
                                    background: `linear-gradient(135deg, ${theme.palette.primary.main} 0%, ${theme.palette.primary.dark} 100%)`,
                                    '&:hover': {
                                        transform: 'scale(1.02)',
                                        boxShadow: '0 8px 25px rgba(0,0,0,0.15)',
                                    },
                                }}
                            >
                                {guardando ? 'Guardando...' : 'Agregar Producto'}
                            </Button>
                        </Grid>
                    </Grid>
                </Box>
            </Paper>

            {/* ===== BUSCADOR ===== */}
            <Box sx={{ mt: 3 }}>
                <TextField
                    fullWidth
                    placeholder="🔍 Buscar producto por nombre..."
                    variant="outlined"
                    value={filtro}
                    onChange={(e) => setFiltro(e.target.value)}
                    sx={{
                        '& .MuiOutlinedInput-root': {
                            borderRadius: 30,
                            background: alpha(theme.palette.background.paper, 0.8),
                            pl: 1,
                            transition: 'all 0.3s ease',
                            '&:hover': {
                                boxShadow: `0 4px 20px ${alpha(theme.palette.primary.main, 0.08)}`,
                            },
                            '&.Mui-focused': {
                                boxShadow: `0 4px 30px ${alpha(theme.palette.primary.main, 0.15)}`,
                            },
                        },
                    }}
                    InputProps={{
                        startAdornment: <Search sx={{ mr: 1, color: 'text.secondary' }} />,
                    }}
                />
            </Box>

            {/* ===== LISTA DE PRODUCTOS ===== */}
            <Box sx={{ mt: 3 }}>
                {cargando ? (
                    <Box sx={{ textAlign: 'center', py: 6 }}>
                        <Typography color="textSecondary">Cargando productos...</Typography>
                    </Box>
                ) : productosFiltrados.length === 0 ? (
                    <Box
                        sx={{
                            textAlign: 'center',
                            py: 6,
                            borderRadius: 4,
                            background: alpha(theme.palette.background.paper, 0.5),
                            border: `2px dashed ${alpha(theme.palette.divider, 0.2)}`,
                        }}
                    >
                        <Inventory sx={{ fontSize: 64, color: 'text.disabled', mb: 2 }} />
                        <Typography variant="h6" color="textSecondary">
                            {filtro ? 'No se encontraron productos' : 'No hay productos registrados'}
                        </Typography>
                        <Typography variant="body2" color="textSecondary" sx={{ mt: 1 }}>
                            {filtro ? 'Intenta con otra búsqueda' : 'Comienza agregando tu primer producto'}
                        </Typography>
                    </Box>
                ) : (
                    <Grid container spacing={2}>
                        {productosFiltrados.map((producto, index) => {
                            const isLowStock = producto.stock <= producto.stockMinimo;
                            return (
                                <Grid item xs={12} sm={6} md={4} key={producto.id}>
                                    <Grow in timeout={200 + index * 50}>
                                        <Card
                                            sx={{
                                                borderRadius: 3,
                                                transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                                                '&:hover': {
                                                    transform: 'translateY(-4px)',
                                                    boxShadow: '0 12px 40px rgba(0,0,0,0.12)',
                                                },
                                                border: `1px solid ${alpha(theme.palette.divider, 0.08)}`,
                                                background: `linear-gradient(135deg, ${alpha(theme.palette.background.paper, 0.95)} 0%, ${alpha(theme.palette.background.default, 0.3)} 100%)`,
                                            }}
                                        >
                                            <CardContent>
                                                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 1 }}>
                                                    <Typography variant="h6" sx={{ fontWeight: 600, fontSize: '1rem' }}>
                                                        {producto.nombre}
                                                    </Typography>
                                                    <Chip
                                                        label={`${producto.stock} uds`}
                                                        size="small"
                                                        icon={isLowStock ? <Warning /> : <CheckCircle />}
                                                        sx={{
                                                            fontWeight: 600,
                                                            borderRadius: 2,
                                                            background: isLowStock
                                                                ? alpha(theme.palette.error.main, 0.15)
                                                                : alpha(theme.palette.success.main, 0.12),
                                                            color: isLowStock
                                                                ? theme.palette.error.main
                                                                : theme.palette.success.main,
                                                        }}
                                                    />
                                                </Box>

                                                <Divider sx={{ my: 1.5 }} />

                                                <Grid container spacing={1}>
                                                    <Grid item xs={6}>
                                                        <Typography variant="caption" color="textSecondary">
                                                            Precio Compra
                                                        </Typography>
                                                        <Typography variant="body2" sx={{ fontWeight: 600 }}>
                                                            ${producto.precioCompra}
                                                        </Typography>
                                                    </Grid>
                                                    <Grid item xs={6}>
                                                        <Typography variant="caption" color="textSecondary">
                                                            Precio Venta
                                                        </Typography>
                                                        <Typography variant="body2" sx={{ fontWeight: 600, color: 'success.main' }}>
                                                            ${producto.precioVenta}
                                                        </Typography>
                                                    </Grid>
                                                    <Grid item xs={12}>
                                                        <Typography variant="caption" color="textSecondary">
                                                            Stock Mínimo
                                                        </Typography>
                                                        <Typography variant="body2" sx={{ fontWeight: 500 }}>
                                                            {producto.stockMinimo} unidades
                                                        </Typography>
                                                    </Grid>
                                                </Grid>

                                                <Box sx={{ display: 'flex', gap: 1, mt: 2 }}>
                                                    <Button
                                                        variant="contained"
                                                        size="small"
                                                        onClick={() => abrirDialogoEditar(producto)}
                                                        startIcon={<Edit />}
                                                        sx={{
                                                            flex: 1,
                                                            borderRadius: 2,
                                                            textTransform: 'none',
                                                            fontWeight: 600,
                                                            py: 1,
                                                            background: `linear-gradient(135deg, ${theme.palette.primary.main} 0%, ${theme.palette.primary.dark} 100%)`,
                                                            '&:hover': {
                                                                transform: 'scale(1.02)',
                                                            },
                                                        }}
                                                    >
                                                        Editar
                                                    </Button>
                                                    <Button
                                                        variant="outlined"
                                                        color="error"
                                                        size="small"
                                                        onClick={() => eliminarProducto(producto.id, producto.nombre)}
                                                        startIcon={<Delete />}
                                                        sx={{
                                                            flex: 0.5,
                                                            borderRadius: 2,
                                                            textTransform: 'none',
                                                            fontWeight: 600,
                                                        }}
                                                    >
                                                        Eliminar
                                                    </Button>
                                                </Box>
                                            </CardContent>
                                        </Card>
                                    </Grow>
                                </Grid>
                            );
                        })}
                    </Grid>
                )}
            </Box>

            {/* ===== DIÁLOGO DE EDICIÓN ===== */}
            <Dialog
                open={dialogoEditar}
                onClose={cerrarDialogoEditar}
                maxWidth="sm"
                fullWidth
                PaperProps={{
                    sx: {
                        borderRadius: 4,
                        p: 1,
                        background: `linear-gradient(135deg, ${alpha(theme.palette.background.paper, 0.98)} 0%, ${alpha(theme.palette.background.default, 0.8)} 100%)`,
                        backdropFilter: 'blur(20px)',
                        border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                        boxShadow: '0 24px 80px rgba(0,0,0,0.15)',
                    }
                }}
            >
                <DialogTitle sx={{ fontWeight: 700, display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Edit color="primary" />
                    Editar Producto
                    <IconButton onClick={cerrarDialogoEditar} sx={{ ml: 'auto' }}>
                        <Close />
                    </IconButton>
                </DialogTitle>
                <DialogContent onKeyDown={(e) => e.key === 'Enter' && guardarCambios()}>
                    <Stack spacing={2.5} sx={{ mt: 1 }}>
                        <TextField
                            label="Nombre"
                            fullWidth
                            value={productoSeleccionado?.nombre || ''}
                            onChange={(e) =>
                                setProductoSeleccionado({ ...productoSeleccionado, nombre: e.target.value })
                            }
                            sx={{
                                '& .MuiOutlinedInput-root': {
                                    borderRadius: 2,
                                    background: alpha(theme.palette.background.paper, 0.6),
                                },
                            }}
                            InputProps={{
                                startAdornment: <Category sx={{ mr: 1, color: 'text.secondary' }} />,
                            }}
                        />
                        <TextField
                            label="Stock"
                            type="number"
                            fullWidth
                            value={productoSeleccionado?.stock || ''}
                            onChange={(e) =>
                                setProductoSeleccionado({ ...productoSeleccionado, stock: e.target.value })
                            }
                            sx={{
                                '& .MuiOutlinedInput-root': {
                                    borderRadius: 2,
                                    background: alpha(theme.palette.background.paper, 0.6),
                                },
                            }}
                            InputProps={{
                                startAdornment: <Numbers sx={{ mr: 1, color: 'text.secondary' }} />,
                            }}
                        />
                        <TextField
                            label="Precio de Compra"
                            type="number"
                            fullWidth
                            value={productoSeleccionado?.precioCompra || ''}
                            onChange={(e) =>
                                setProductoSeleccionado({ ...productoSeleccionado, precioCompra: e.target.value })
                            }
                            sx={{
                                '& .MuiOutlinedInput-root': {
                                    borderRadius: 2,
                                    background: alpha(theme.palette.background.paper, 0.6),
                                },
                            }}
                            InputProps={{
                                startAdornment: <AttachMoney sx={{ mr: 1, color: 'text.secondary' }} />,
                            }}
                        />
                        <TextField
                            label="Precio de Venta"
                            type="number"
                            fullWidth
                            value={productoSeleccionado?.precioVenta || ''}
                            onChange={(e) =>
                                setProductoSeleccionado({ ...productoSeleccionado, precioVenta: e.target.value })
                            }
                            sx={{
                                '& .MuiOutlinedInput-root': {
                                    borderRadius: 2,
                                    background: alpha(theme.palette.background.paper, 0.6),
                                },
                            }}
                            InputProps={{
                                startAdornment: <LocalOffer sx={{ mr: 1, color: 'text.secondary' }} />,
                            }}
                        />
                        <TextField
                            label="Stock Mínimo"
                            type="number"
                            fullWidth
                            value={productoSeleccionado?.stockMinimo || ''}
                            onChange={(e) =>
                                setProductoSeleccionado({ ...productoSeleccionado, stockMinimo: e.target.value })
                            }
                            sx={{
                                '& .MuiOutlinedInput-root': {
                                    borderRadius: 2,
                                    background: alpha(theme.palette.background.paper, 0.6),
                                },
                            }}
                            InputProps={{
                                startAdornment: <Warning sx={{ mr: 1, color: 'text.secondary' }} />,
                            }}
                        />
                    </Stack>
                </DialogContent>
                <DialogActions sx={{ p: 3, pt: 0, gap: 1 }}>
                    <Button
                        onClick={cerrarDialogoEditar}
                        variant="outlined"
                        color="secondary"
                        startIcon={<Cancel />}
                        sx={{ borderRadius: 2, textTransform: 'none', fontWeight: 600 }}
                    >
                        Cancelar
                    </Button>
                    <Button
                        onClick={guardarCambios}
                        variant="contained"
                        startIcon={<Save />}
                        sx={{
                            borderRadius: 2,
                            px: 3,
                            py: 1,
                            fontWeight: 600,
                            textTransform: 'none',
                            background: `linear-gradient(135deg, ${theme.palette.primary.main} 0%, ${theme.palette.primary.dark} 100%)`,
                            '&:hover': {
                                transform: 'scale(1.02)',
                            },
                        }}
                    >
                        Guardar Cambios
                    </Button>
                </DialogActions>
            </Dialog>

            {/* ===== SNACKBAR PERSONALIZADO ===== */}
            <Snackbar
                open={alertaStock}
                autoHideDuration={6000}
                onClose={() => setAlertaStock(false)}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
            >
                <Paper
                    sx={{
                        p: 2,
                        borderRadius: 3,
                        background:
                            tipoAlerta === 'success'
                                ? `linear-gradient(135deg, ${theme.palette.success.main} 0%, ${theme.palette.success.dark} 100%)`
                                : tipoAlerta === 'error'
                                    ? `linear-gradient(135deg, ${theme.palette.error.main} 0%, ${theme.palette.error.dark} 100%)`
                                    : `linear-gradient(135deg, ${theme.palette.info.main} 0%, ${theme.palette.info.dark} 100%)`,
                        color: 'white',
                        fontWeight: 500,
                        boxShadow: '0 8px 32px rgba(0,0,0,0.15)',
                        display: 'flex',
                        alignItems: 'center',
                        gap: 1.5,
                        minWidth: 300,
                    }}
                >
                    {tipoAlerta === 'success' && <CheckCircle />}
                    {tipoAlerta === 'error' && <Warning />}
                    {tipoAlerta === 'info' && <Assessment />}
                    {mensajeAlerta}
                </Paper>
            </Snackbar>
        </Box>
    );
}

export default Stock;