import React, { useEffect, useState } from 'react';
import {
    Box,
    Typography,
    Button,
    List,
    ListItem,
    ListItemText,
    Divider,
    Paper,
    Grid,
    Card,
    CardContent,
    alpha,
    useTheme,
    Chip,
    Container,
    Skeleton,
} from '@mui/material';
import {
    TrendingUp,
    TrendingDown,
    AttachMoney,
    Store,
    CalendarToday,
    Assessment,
    ArrowBack,
    Receipt,
    Inventory,
} from '@mui/icons-material';
import { ref, get } from 'firebase/database';
import { db } from './firebaseConfig';
import { useNavigate } from 'react-router-dom';
import lumarfoto from './lumar.png';

function Estadisticas() {
    const theme = useTheme();
    const navigate = useNavigate();

    // ===== STATES =====
    const [totalVentasDiarias, setTotalVentasDiarias] = useState(0);
    const [totalVentasMensuales, setTotalVentasMensuales] = useState(0);
    const [acumuladoHoy, setAcumuladoHoy] = useState(0);
    const [gananciaDiaria, setGananciaDiaria] = useState(0);
    const [gananciaMensual, setGananciaMensual] = useState(0);
    const [detalleProductos, setDetalleProductos] = useState([]);
    const [cargando, setCargando] = useState(true);
    const [resumenProductos, setResumenProductos] = useState([]);
    const [productosMasVendidos, setProductosMasVendidos] = useState([]);

    const fechaActual = new Date();
    const mesActual = fechaActual.toISOString().slice(0, 7);
    const fechaHoy = fechaActual.toISOString().split('T')[0];
    const nombreMes = fechaActual.toLocaleString('es-ES', { month: 'long', year: 'numeric' });

    // ===== FUNCIONES =====
    useEffect(() => {
        const cargarEstadisticas = async () => {
            setCargando(true);
            try {
                const ventasRef = ref(db, 'ventas');
                const acumuladoMensualRef = ref(db, `acumuladoMensual/${mesActual}`);

                const ventasSnapshot = await get(ventasRef);
                if (ventasSnapshot.exists()) {
                    const ventas = Object.values(ventasSnapshot.val());
                    console.log("📊 Ventas descargadas:", ventas.length);

                    // Ventas del día
                    const ventasDelDia = ventas.filter((venta) => venta.fecha === fechaHoy);
                    const totalDelDia = ventasDelDia.reduce((total, venta) => total + venta.totalVenta, 0);
                    const gananciaDelDia = ventasDelDia.reduce(
                        (ganancia, venta) =>
                            ganancia + (venta.totalVenta - (venta.precioCompra || 0) * venta.cantidad),
                        0
                    );

                    setTotalVentasDiarias(totalDelDia);
                    setGananciaDiaria(gananciaDelDia);

                    // Ventas hasta hoy
                    const ventasHastaHoy = ventas.filter((venta) => venta.fecha <= fechaHoy);
                    const totalHastaHoy = ventasHastaHoy.reduce((total, venta) => total + venta.totalVenta, 0);
                    setAcumuladoHoy(totalHastaHoy);

                    const gananciaTotalMensual = ventasHastaHoy.reduce(
                        (ganancia, venta) =>
                            ganancia + (venta.totalVenta - (venta.precioCompra || 0) * venta.cantidad),
                        0
                    );
                    setGananciaMensual(gananciaTotalMensual);

                    // Detalle de productos
                    const productosVendidos = ventas.map((venta) => ({
                        nombre: venta.producto,
                        cantidad: venta.cantidad,
                        total: venta.totalVenta,
                        fecha: venta.fecha,
                    }));
                    setDetalleProductos(productosVendidos);

                    // Resumen por producto
                    const resumen = {};
                    productosVendidos.forEach((item) => {
                        if (!resumen[item.nombre]) {
                            resumen[item.nombre] = { cantidad: 0, total: 0 };
                        }
                        resumen[item.nombre].cantidad += item.cantidad;
                        resumen[item.nombre].total += item.total;
                    });

                    const resumenArray = Object.entries(resumen).map(([nombre, data]) => ({
                        nombre,
                        cantidad: data.cantidad,
                        total: data.total,
                    }));
                    setResumenProductos(resumenArray);

                    // Productos más vendidos
                    const ordenados = [...resumenArray].sort((a, b) => b.cantidad - a.cantidad);
                    setProductosMasVendidos(ordenados.slice(0, 5));

                } else {
                    console.log("📊 No se encontraron ventas");
                }

                // Acumulado mensual
                const acumuladoMensualSnapshot = await get(acumuladoMensualRef);
                if (acumuladoMensualSnapshot.exists()) {
                    setTotalVentasMensuales(acumuladoMensualSnapshot.val());
                }

            } catch (error) {
                console.error("❌ Error cargando estadísticas:", error);
            } finally {
                setCargando(false);
            }
        };

        cargarEstadisticas();
    }, [mesActual, fechaHoy]);

    // ===== HELPER =====
    const formatearFecha = (fecha) => {
        const opciones = { year: 'numeric', month: 'short', day: 'numeric' };
        return new Date(fecha + 'T00:00:00').toLocaleDateString('es-ES', opciones);
    };

    // ===== RENDER =====
    return (
        <Container maxWidth="lg" sx={{ py: 4 }}>
            {/* ===== HEADER ===== */}
            <Paper
                elevation={0}
                sx={{
                    p: 3,
                    borderRadius: 4,
                    mb: 4,
                    background: `linear-gradient(135deg, ${alpha(theme.palette.background.paper, 0.95)} 0%, ${alpha(theme.palette.background.default, 0.5)} 100%)`,
                    border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                }}
            >
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 2 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                        <Box
                            component="img"
                            src={lumarfoto}
                            alt="Logo Lumar"
                            sx={{
                                width: 50,
                                height: 50,
                                borderRadius: '50%',
                                objectFit: 'contain',
                                boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                            }}
                        />
                        <Box>
                            <Typography variant="h4" sx={{ fontWeight: 700 }}>
                                Estadísticas
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                Resumen de ventas y rendimiento
                            </Typography>
                        </Box>
                    </Box>
                    <Chip
                        icon={<CalendarToday />}
                        label={nombreMes.charAt(0).toUpperCase() + nombreMes.slice(1)}
                        sx={{
                            borderRadius: 2,
                            fontWeight: 600,
                            py: 2,
                            px: 1,
                            bgcolor: alpha(theme.palette.primary.main, 0.08),
                        }}
                    />
                </Box>
            </Paper>

            {cargando ? (
                // ===== SKELETON LOADING =====
                <Grid container spacing={3}>
                    {[1, 2, 3, 4].map((i) => (
                        <Grid item xs={12} sm={6} md={3} key={i}>
                            <Skeleton variant="rounded" height={120} sx={{ borderRadius: 3 }} />
                        </Grid>
                    ))}
                </Grid>
            ) : (
                // ===== TARJETAS DE ESTADÍSTICAS =====
                <>
                    <Grid container spacing={3} sx={{ mb: 4 }}>
                        <Grid item xs={12} sm={6} md={3}>
                            <Card
                                sx={{
                                    borderRadius: 3,
                                    background: `linear-gradient(135deg, ${alpha(theme.palette.info.main, 0.05)}, ${alpha(theme.palette.info.light, 0.02)})`,
                                    border: `1px solid ${alpha(theme.palette.info.main, 0.15)}`,
                                    transition: 'all 0.3s ease',
                                    '&:hover': {
                                        transform: 'translateY(-4px)',
                                        boxShadow: '0 8px 30px rgba(0,0,0,0.08)',
                                    },
                                }}
                            >
                                <CardContent>
                                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                                        <Box>
                                            <Typography variant="caption" color="textSecondary">
                                                Ventas Hoy
                                            </Typography>
                                            <Typography variant="h5" sx={{ fontWeight: 700, color: theme.palette.info.main }}>
                                                ${totalVentasDiarias.toFixed(2)}
                                            </Typography>
                                        </Box>
                                        <Store sx={{ fontSize: 40, color: theme.palette.info.main, opacity: 0.3 }} />
                                    </Box>
                                    <Typography variant="caption" color="textSecondary">
                                        {fechaHoy}
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>

                        <Grid item xs={12} sm={6} md={3}>
                            <Card
                                sx={{
                                    borderRadius: 3,
                                    background: `linear-gradient(135deg, ${alpha(theme.palette.success.main, 0.05)}, ${alpha(theme.palette.success.light, 0.02)})`,
                                    border: `1px solid ${alpha(theme.palette.success.main, 0.15)}`,
                                    transition: 'all 0.3s ease',
                                    '&:hover': {
                                        transform: 'translateY(-4px)',
                                        boxShadow: '0 8px 30px rgba(0,0,0,0.08)',
                                    },
                                }}
                            >
                                <CardContent>
                                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                                        <Box>
                                            <Typography variant="caption" color="textSecondary">
                                                Ganancia Hoy
                                            </Typography>
                                            <Typography variant="h5" sx={{ fontWeight: 700, color: theme.palette.success.main }}>
                                                ${gananciaDiaria.toFixed(2)}
                                            </Typography>
                                        </Box>
                                        <TrendingUp sx={{ fontSize: 40, color: theme.palette.success.main, opacity: 0.3 }} />
                                    </Box>
                                    <Typography variant="caption" color="textSecondary">
                                        {gananciaDiaria >= 0 ? '📈 Positiva' : '📉 Negativa'}
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>

                        <Grid item xs={12} sm={6} md={3}>
                            <Card
                                sx={{
                                    borderRadius: 3,
                                    background: `linear-gradient(135deg, ${alpha(theme.palette.primary.main, 0.05)}, ${alpha(theme.palette.primary.light, 0.02)})`,
                                    border: `1px solid ${alpha(theme.palette.primary.main, 0.15)}`,
                                    transition: 'all 0.3s ease',
                                    '&:hover': {
                                        transform: 'translateY(-4px)',
                                        boxShadow: '0 8px 30px rgba(0,0,0,0.08)',
                                    },
                                }}
                            >
                                <CardContent>
                                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                                        <Box>
                                            <Typography variant="caption" color="textSecondary">
                                                Acumulado Mes
                                            </Typography>
                                            <Typography variant="h5" sx={{ fontWeight: 700, color: theme.palette.primary.main }}>
                                                ${totalVentasMensuales.toFixed(2)}
                                            </Typography>
                                        </Box>
                                        <Assessment sx={{ fontSize: 40, color: theme.palette.primary.main, opacity: 0.3 }} />
                                    </Box>
                                    <Typography variant="caption" color="textSecondary">
                                        {nombreMes}
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>

                        <Grid item xs={12} sm={6} md={3}>
                            <Card
                                sx={{
                                    borderRadius: 3,
                                    background: `linear-gradient(135deg, ${alpha(theme.palette.secondary.main, 0.05)}, ${alpha(theme.palette.secondary.light, 0.02)})`,
                                    border: `1px solid ${alpha(theme.palette.secondary.main, 0.15)}`,
                                    transition: 'all 0.3s ease',
                                    '&:hover': {
                                        transform: 'translateY(-4px)',
                                        boxShadow: '0 8px 30px rgba(0,0,0,0.08)',
                                    },
                                }}
                            >
                                <CardContent>
                                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                                        <Box>
                                            <Typography variant="caption" color="textSecondary">
                                                Ganancia Mes
                                            </Typography>
                                            <Typography variant="h5" sx={{ fontWeight: 700, color: theme.palette.secondary.main }}>
                                                ${gananciaMensual.toFixed(2)}
                                            </Typography>
                                        </Box>
                                        <AttachMoney sx={{ fontSize: 40, color: theme.palette.secondary.main, opacity: 0.3 }} />
                                    </Box>
                                    <Typography variant="caption" color="textSecondary">
                                        {gananciaMensual >= 0 ? '📈 Rentable' : '📉 Pérdida'}
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>
                    </Grid>

                    {/* ===== PRODUCTOS MÁS VENDIDOS ===== */}
                    {productosMasVendidos.length > 0 && (
                        <Paper
                            elevation={0}
                            sx={{
                                p: 3,
                                borderRadius: 4,
                                mb: 4,
                                background: `linear-gradient(135deg, ${alpha(theme.palette.background.paper, 0.95)} 0%, ${alpha(theme.palette.background.default, 0.5)} 100%)`,
                                border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                            }}
                        >
                            <Typography variant="h6" sx={{ fontWeight: 600, mb: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
                                <TrendingUp color="primary" />
                                Productos Más Vendidos
                            </Typography>
                            <Grid container spacing={2}>
                                {productosMasVendidos.map((producto, index) => (
                                    <Grid item xs={12} sm={6} md={4} key={index}>
                                        <Box
                                            sx={{
                                                display: 'flex',
                                                alignItems: 'center',
                                                gap: 2,
                                                p: 2,
                                                borderRadius: 2,
                                                bgcolor: alpha(theme.palette.background.paper, 0.5),
                                                border: `1px solid ${alpha(theme.palette.divider, 0.05)}`,
                                            }}
                                        >
                                            <Chip
                                                label={`#${index + 1}`}
                                                size="small"
                                                sx={{
                                                    fontWeight: 700,
                                                    bgcolor: index === 0 ? theme.palette.warning.main : alpha(theme.palette.primary.main, 0.1),
                                                    color: index === 0 ? 'white' : 'inherit',
                                                }}
                                            />
                                            <Box sx={{ flex: 1 }}>
                                                <Typography variant="body1" sx={{ fontWeight: 600 }}>
                                                    {producto.nombre}
                                                </Typography>
                                                <Typography variant="caption" color="textSecondary">
                                                    {producto.cantidad} unidades · ${producto.total.toFixed(2)}
                                                </Typography>
                                            </Box>
                                        </Box>
                                    </Grid>
                                ))}
                            </Grid>
                        </Paper>
                    )}

                    {/* ===== DETALLE DE PRODUCTOS ===== */}
                    <Paper
                        elevation={0}
                        sx={{
                            p: 3,
                            borderRadius: 4,
                            background: `linear-gradient(135deg, ${alpha(theme.palette.background.paper, 0.95)} 0%, ${alpha(theme.palette.background.default, 0.5)} 100%)`,
                            border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                        }}
                    >
                        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2, flexWrap: 'wrap', gap: 1 }}>
                            <Typography variant="h6" sx={{ fontWeight: 600, display: 'flex', alignItems: 'center', gap: 1 }}>
                                <Receipt color="primary" />
                                Detalle de Productos Vendidos
                            </Typography>
                            <Chip
                                label={`${detalleProductos.length} registros`}
                                size="small"
                                sx={{ borderRadius: 2 }}
                            />
                        </Box>

                        <Divider sx={{ mb: 2 }} />

                        {detalleProductos.length === 0 ? (
                            <Box sx={{ textAlign: 'center', py: 4 }}>
                                <Inventory sx={{ fontSize: 48, color: 'text.disabled', mb: 1 }} />
                                <Typography color="textSecondary">No hay productos vendidos</Typography>
                            </Box>
                        ) : (
                            <List sx={{ maxHeight: 400, overflow: 'auto' }}>
                                {detalleProductos.map((producto, index) => (
                                    <React.Fragment key={index}>
                                        <ListItem
                                            sx={{
                                                borderRadius: 2,
                                                transition: 'all 0.2s ease',
                                                '&:hover': {
                                                    bgcolor: alpha(theme.palette.primary.main, 0.04),
                                                },
                                            }}
                                        >
                                            <ListItemText
                                                primary={
                                                    <Typography sx={{ fontWeight: 500 }}>
                                                        {producto.nombre}
                                                    </Typography>
                                                }
                                                secondary={
                                                    <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
                                                        <Typography variant="caption" component="span">
                                                            Cantidad: <strong>{producto.cantidad}</strong>
                                                        </Typography>
                                                        <Typography variant="caption" component="span">
                                                            Total: <strong style={{ color: theme.palette.success.main }}>
                                                                ${producto.total.toFixed(2)}
                                                            </strong>
                                                        </Typography>
                                                        <Typography variant="caption" component="span" color="textSecondary">
                                                            {formatearFecha(producto.fecha)}
                                                        </Typography>
                                                    </Box>
                                                }
                                            />
                                        </ListItem>
                                        {index < detalleProductos.length - 1 && <Divider sx={{ opacity: 0.3 }} />}
                                    </React.Fragment>
                                ))}
                            </List>
                        )}
                    </Paper>
                </>
            )}

            {/* ===== BOTÓN VOLVER ===== */}
            <Button
                variant="contained"
                color="warning"
                onClick={() => navigate(-1)}
                startIcon={<ArrowBack />}
                sx={{
                    position: 'fixed',
                    bottom: 24,
                    right: 24,
                    borderRadius: 3,
                    px: 3,
                    py: 1.5,
                    fontWeight: 600,
                    textTransform: 'none',
                    boxShadow: '0 8px 25px rgba(255,152,0,0.3)',
                    '&:hover': {
                        transform: 'scale(1.05)',
                        boxShadow: '0 12px 35px rgba(255,152,0,0.4)',
                    },
                }}
            >
                Volver
            </Button>
        </Container>
    );
}

export default Estadisticas;