import React, { useState, useEffect } from 'react';
import {
    Box,
    Typography,
    TextField,
    Button,
    List,
    ListItem,
    ListItemText,
    Snackbar,
    Container,
    Paper,
    Card,
    CardContent,
    Grid,
    Chip,
    Divider,
    IconButton,
    Grow,
    Zoom,
    useTheme,
    alpha,
} from '@mui/material';
import { ref, get, set, push } from 'firebase/database';
import { db } from './firebaseConfig';
import { useNavigate } from 'react-router-dom';
import {
    ShoppingCart,
    Search,
    AddShoppingCart,
    CheckCircle,
    Print,
    ArrowBack,
    RemoveShoppingCart,
    AttachMoney,
    TrendingUp,
    Today,
} from '@mui/icons-material';
import lumarfoto from './lumar.png';

function Ventas() {
    const theme = useTheme();
    const navigate = useNavigate();

    // ===== STATES =====
    const [productos, setProductos] = useState([]);
    const [filtro, setFiltro] = useState('');
    const [itemsSeleccionados, setItemsSeleccionados] = useState([]);
    const [cantidadVenta, setCantidadVenta] = useState({});
    const [mensaje, setMensaje] = useState('');
    const [snackbarOpen, setSnackbarOpen] = useState(false);
    const [snackbarSeverity, setSnackbarSeverity] = useState('success');
    const [totalVentasDiarias, setTotalVentasDiarias] = useState(0);
    const [totalVentasMensuales, setTotalVentasMensuales] = useState(0);
    const [cargando, setCargando] = useState(true);

    const fechaActual = new Date();
    const mesActual = fechaActual.toISOString().slice(0, 7);

    // ===== FUNCIONES =====
    const cargarDatos = async () => {
        setCargando(true);
        try {
            const productosRef = ref(db, 'productos');
            const ventasRef = ref(db, 'ventas');
            const acumuladoMensualRef = ref(db, `acumuladoMensual/${mesActual}`);

            const productosSnapshot = await get(productosRef);
            setProductos(productosSnapshot.exists() ? Object.values(productosSnapshot.val()) : []);

            const ventasSnapshot = await get(ventasRef);
            if (ventasSnapshot.exists()) {
                const ventas = Object.values(ventasSnapshot.val());
                const ventasDelDia = ventas.filter(
                    (venta) => venta.fecha === fechaActual.toISOString().split('T')[0]
                );
                const totalDelDia = ventasDelDia.reduce((total, venta) => total + venta.totalVenta, 0);
                setTotalVentasDiarias(totalDelDia);
            }

            const acumuladoMensualSnapshot = await get(acumuladoMensualRef);
            if (acumuladoMensualSnapshot.exists()) {
                setTotalVentasMensuales(acumuladoMensualSnapshot.val());
            } else {
                await set(acumuladoMensualRef, 0);
                setTotalVentasMensuales(0);
            }
        } catch (error) {
            mostrarSnackbar('Error al cargar datos', 'error');
        } finally {
            setCargando(false);
        }
    };

    useEffect(() => {
        cargarDatos();
    }, []);

    const mostrarSnackbar = (mensaje, severity = 'success') => {
        setMensaje(mensaje);
        setSnackbarSeverity(severity);
        setSnackbarOpen(true);
    };

    const agregarItem = (producto) => {
        const cantidad = Number(cantidadVenta[producto.nombre] || 0);
        if (cantidad <= 0 || cantidad > producto.stock) {
            mostrarSnackbar('Cantidad no válida', 'error');
            return;
        }

        const existente = itemsSeleccionados.find((item) => item.nombre === producto.nombre);
        if (existente) {
            const nuevosItems = itemsSeleccionados.map((item) =>
                item.nombre === producto.nombre
                    ? { ...item, cantidad: item.cantidad + cantidad }
                    : item
            );
            setItemsSeleccionados(nuevosItems);
        } else {
            setItemsSeleccionados([...itemsSeleccionados, { ...producto, cantidad }]);
        }

        setCantidadVenta({ ...cantidadVenta, [producto.nombre]: '' });
        mostrarSnackbar(`✅ Producto agregado: ${producto.nombre} x${cantidad}`, 'success');
    };

    const eliminarItem = (nombre) => {
        setItemsSeleccionados(itemsSeleccionados.filter((item) => item.nombre !== nombre));
        mostrarSnackbar(`🗑️ Producto removido: ${nombre}`, 'info');
    };

    const confirmarVenta = async () => {
        if (itemsSeleccionados.length === 0) {
            mostrarSnackbar('No hay productos seleccionados', 'error');
            return;
        }

        let totalVenta = 0;

        try {
            for (const item of itemsSeleccionados) {
                const producto = productos.find((p) => p.nombre === item.nombre);
                if (producto) {
                    producto.stock -= item.cantidad;
                    const totalItem = item.cantidad * producto.precioVenta;
                    totalVenta += totalItem;

                    await set(ref(db, `productos/${producto.nombre}`), producto);
                    await push(ref(db, 'ventas'), {
                        producto: producto.nombre,
                        cantidad: item.cantidad,
                        totalVenta: totalItem,
                        fecha: fechaActual.toISOString().split('T')[0],
                    });
                }
            }

            const acumuladoMensualRef = ref(db, `acumuladoMensual/${mesActual}`);
            const nuevoTotalMensual = totalVentasMensuales + totalVenta;
            await set(acumuladoMensualRef, nuevoTotalMensual);

            setItemsSeleccionados([]);
            setTotalVentasDiarias((prev) => prev + totalVenta);
            setTotalVentasMensuales(nuevoTotalMensual);
            mostrarSnackbar(`✅ Venta confirmada. Total: $${totalVenta.toFixed(2)}`, 'success');
            cargarDatos();
        } catch (error) {
            mostrarSnackbar('Error al confirmar venta', 'error');
        }
    };

    const imprimirTicket = () => {
        if (itemsSeleccionados.length === 0) {
            mostrarSnackbar('No hay items para imprimir', 'error');
            return;
        }

        const contenido = `
        ============================================
                    🧾 TICKET DE COMPRA
        ============================================
        
        Fecha: ${new Date().toLocaleString()}
        --------------------------------------------
        
        ${itemsSeleccionados
                .map(
                    (item) =>
                        `  ${item.nombre.padEnd(25)} x${item.cantidad}  $${(item.cantidad * item.precioVenta).toFixed(2)}`
                )
                .join('\n')}
        
        --------------------------------------------
        Subtotal:${' '.repeat(30)} $${subtotal.toFixed(2)}
        ============================================
        
        ¡Gracias por su compra!
        ============================================
        `;

        const ventana = window.open('', '_blank');
        ventana.document.write(`
            <html>
                <head>
                    <style>
                        body { 
                            font-family: 'Courier New', monospace;
                            padding: 40px;
                            max-width: 400px;
                            margin: 0 auto;
                            background: white;
                        }
                        pre {
                            white-space: pre-wrap;
                            font-size: 14px;
                            line-height: 1.6;
                        }
                        @media print {
                            body { padding: 20px; }
                            .no-print { display: none; }
                        }
                    </style>
                </head>
                <body>
                    <pre>${contenido}</pre>
                    <button class="no-print" onclick="window.print()" style="margin-top:20px;padding:10px 20px;border:none;background:#1976d2;color:white;border-radius:8px;cursor:pointer;font-size:16px;">
                        🖨️ Imprimir
                    </button>
                    <button class="no-print" onclick="window.close()" style="margin-top:20px;margin-left:10px;padding:10px 20px;border:none;background:#666;color:white;border-radius:8px;cursor:pointer;font-size:16px;">
                        ✖ Cerrar
                    </button>
                </body>
            </html>
        `);
        ventana.document.close();
    };

    const subtotal = itemsSeleccionados.reduce(
        (total, item) => total + item.cantidad * item.precioVenta,
        0
    );

    const productosFiltrados = productos.filter((producto) =>
        typeof producto.nombre === 'string' &&
        producto.nombre.toLowerCase().includes(filtro.toLowerCase())
    );

    // ===== RENDER =====
    return (
        <Container maxWidth="lg" sx={{ py: 4 }}>
            {/* ===== HEADER ===== */}
            <Paper
                elevation={0}
                sx={{
                    p: 3,
                    borderRadius: 4,
                    background: `linear-gradient(135deg, ${alpha(theme.palette.background.paper, 0.95)} 0%, ${alpha(theme.palette.background.default, 0.5)} 100%)`,
                    backdropFilter: 'blur(10px)',
                    border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                    boxShadow: '0 8px 32px rgba(0,0,0,0.08)',
                    mb: 3,
                }}
            >
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 3, flexWrap: 'wrap', gap: 2 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                        <Box
                            component="img"
                            src={lumarfoto}
                            alt="Logo"
                            sx={{
                                width: 60,
                                height: 60,
                                borderRadius: '50%',
                                objectFit: 'contain',
                                boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                            }}
                        />
                        <Box>
                            <Typography variant="h4" sx={{ fontWeight: 700 }}>
                                Ventas
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                Gestiona tus ventas de forma rápida y sencilla
                            </Typography>
                        </Box>
                    </Box>

                    {/* Estadísticas */}
                    <Box sx={{ display: { xs: 'none', md: 'flex' }, gap: 2 }}>
                        <Paper
                            sx={{
                                px: 3,
                                py: 1.5,
                                borderRadius: 3,
                                background: `linear-gradient(135deg, ${alpha(theme.palette.info.main, 0.1)}, ${alpha(theme.palette.info.light, 0.05)})`,
                                border: `1px solid ${alpha(theme.palette.info.main, 0.2)}`,
                            }}
                        >
                            <Typography variant="caption" color="textSecondary">
                                <Today sx={{ fontSize: 14, verticalAlign: 'middle', mr: 0.5 }} />
                                Hoy
                            </Typography>
                            <Typography variant="h6" sx={{ fontWeight: 700, color: theme.palette.info.main }}>
                                ${totalVentasDiarias.toFixed(2)}
                            </Typography>
                        </Paper>
                        <Paper
                            sx={{
                                px: 3,
                                py: 1.5,
                                borderRadius: 3,
                                background: `linear-gradient(135deg, ${alpha(theme.palette.success.main, 0.1)}, ${alpha(theme.palette.success.light, 0.05)})`,
                                border: `1px solid ${alpha(theme.palette.success.main, 0.2)}`,
                            }}
                        >
                            <Typography variant="caption" color="textSecondary">
                                <TrendingUp sx={{ fontSize: 14, verticalAlign: 'middle', mr: 0.5 }} />
                                Mes
                            </Typography>
                            <Typography variant="h6" sx={{ fontWeight: 700, color: theme.palette.success.main }}>
                                ${totalVentasMensuales.toFixed(2)}
                            </Typography>
                        </Paper>
                    </Box>
                </Box>

                {/* Buscador */}
                <TextField
                    fullWidth
                    placeholder="🔍 Buscar producto por nombre..."
                    variant="outlined"
                    value={filtro}
                    onChange={(e) => setFiltro(e.target.value)}
                    sx={{
                        mb: 3,
                        '& .MuiOutlinedInput-root': {
                            borderRadius: 4,
                            background: alpha(theme.palette.background.paper, 0.8),
                            '& fieldset': {
                                borderColor: alpha(theme.palette.divider, 0.2),
                            },
                        },
                    }}
                    InputProps={{
                        startAdornment: <Search sx={{ mr: 1, color: 'text.secondary' }} />,
                    }}
                />

                {/* ===== LISTA DE PRODUCTOS ===== */}
                <Grid container spacing={2}>
                    {productosFiltrados.map((producto, index) => {
                        const isLowStock = producto.stock <= 5;
                        return (
                            <Grid item xs={12} sm={6} md={4} key={index}>
                                <Grow in timeout={300 + index * 50}>
                                    <Card
                                        sx={{
                                            borderRadius: 3,
                                            transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                                            '&:hover': {
                                                transform: 'translateY(-4px)',
                                                boxShadow: '0 12px 40px rgba(0,0,0,0.12)',
                                                borderColor: theme.palette.primary.main,
                                            },
                                            border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                                            background: `linear-gradient(135deg, ${alpha(theme.palette.background.paper, 0.9)} 0%, ${alpha(theme.palette.background.default, 0.5)} 100%)`,
                                        }}
                                    >
                                        <CardContent>
                                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                                <Box>
                                                    <Typography variant="h6" sx={{ fontWeight: 600 }}>
                                                        {producto.nombre}
                                                    </Typography>
                                                    <Typography variant="body2" color="textSecondary">
                                                        <AttachMoney sx={{ fontSize: 16, verticalAlign: 'middle' }} />
                                                        {producto.precioVenta}
                                                    </Typography>
                                                </Box>
                                                <Chip
                                                    label={`Stock: ${producto.stock}`}
                                                    size="small"
                                                    sx={{
                                                        fontWeight: 600,
                                                        borderRadius: 2,
                                                        background: isLowStock
                                                            ? alpha(theme.palette.error.main, 0.15)
                                                            : alpha(theme.palette.success.main, 0.15),
                                                        color: isLowStock
                                                            ? theme.palette.error.main
                                                            : theme.palette.success.main,
                                                    }}
                                                />
                                            </Box>

                                            <Box sx={{ display: 'flex', gap: 1, mt: 2 }}>
                                                <TextField
                                                    type="number"
                                                    size="small"
                                                    placeholder="Cant."
                                                    value={cantidadVenta[producto.nombre] || ''}
                                                    onChange={(e) =>
                                                        setCantidadVenta({
                                                            ...cantidadVenta,
                                                            [producto.nombre]: e.target.value,
                                                        })
                                                    }
                                                    onKeyDown={(e) => {
                                                        if (e.key === 'Enter') agregarItem(producto);
                                                    }}
                                                    sx={{
                                                        flex: 1,
                                                        '& .MuiOutlinedInput-root': {
                                                            borderRadius: 2,
                                                        },
                                                    }}
                                                />
                                                <Button
                                                    variant="contained"
                                                    color="primary"
                                                    size="small"
                                                    onClick={() => agregarItem(producto)}
                                                    startIcon={<AddShoppingCart />}
                                                    disabled={producto.stock === 0}
                                                    sx={{
                                                        borderRadius: 2,
                                                        fontWeight: 600,
                                                        textTransform: 'none',
                                                        '&:hover': {
                                                            transform: 'scale(1.02)',
                                                            boxShadow: '0 8px 25px rgba(0,0,0,0.15)',
                                                        },
                                                    }}
                                                >
                                                    Agregar
                                                </Button>
                                            </Box>
                                        </CardContent>
                                    </Card>
                                </Grow>
                            </Grid>
                        );
                    })}
                </Grid>

                {productosFiltrados.length === 0 && (
                    <Box sx={{ textAlign: 'center', py: 4 }}>
                        <Typography variant="body1" color="textSecondary">
                            {filtro ? 'No se encontraron productos' : 'No hay productos disponibles'}
                        </Typography>
                    </Box>
                )}
            </Paper>

            {/* ===== CARRITO ===== */}
            <Box
                sx={{
                    animation: 'fadeInUp 0.5s ease-out',
                    '@keyframes fadeInUp': {
                        from: {
                            opacity: 0,
                            transform: 'translateY(20px)',
                        },
                        to: {
                            opacity: 1,
                            transform: 'translateY(0)',
                        },
                    },
                }}
            >
                <Paper
                    elevation={0}
                    sx={{
                        mt: 4,
                        p: 3,
                        borderRadius: 4,
                        background: `linear-gradient(135deg, ${alpha(theme.palette.primary.main, 0.03)}, ${alpha(theme.palette.secondary.main, 0.03)})`,
                        border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
                    }}
                >
                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
                        <Typography variant="h5" sx={{ fontWeight: 700 }}>
                            <ShoppingCart sx={{ verticalAlign: 'middle', mr: 1 }} />
                            Carrito
                        </Typography>
                        <Chip
                            label={`${itemsSeleccionados.length} items`}
                            color="primary"
                            size="medium"
                            sx={{ borderRadius: 2, fontWeight: 600 }}
                        />
                    </Box>

                    <Divider sx={{ mb: 2 }} />

                    {itemsSeleccionados.length === 0 ? (
                        <Box sx={{ textAlign: 'center', py: 3 }}>
                            <RemoveShoppingCart sx={{ fontSize: 48, color: 'text.disabled', mb: 1 }} />
                            <Typography color="textSecondary">El carrito está vacío</Typography>
                        </Box>
                    ) : (
                        <>
                            <List sx={{ maxHeight: 300, overflow: 'auto' }}>
                                {itemsSeleccionados.map((item, index) => (
                                    <Zoom in key={index}>
                                        <ListItem
                                            secondaryAction={
                                                <IconButton
                                                    edge="end"
                                                    onClick={() => eliminarItem(item.nombre)}
                                                    color="error"
                                                    size="small"
                                                >
                                                    <RemoveShoppingCart />
                                                </IconButton>
                                            }
                                            sx={{
                                                borderRadius: 2,
                                                mb: 1,
                                                background: alpha(theme.palette.background.paper, 0.5),
                                                border: `1px solid ${alpha(theme.palette.divider, 0.05)}`,
                                            }}
                                        >
                                            <ListItemText
                                                primary={
                                                    <Typography sx={{ fontWeight: 600 }}>
                                                        {item.nombre}
                                                    </Typography>
                                                }
                                                secondary={
                                                    <>
                                                        Cantidad: {item.cantidad}
                                                        <Box component="span" sx={{ ml: 2, fontWeight: 600, color: 'success.main' }}>
                                                            ${(item.cantidad * item.precioVenta).toFixed(2)}
                                                        </Box>
                                                    </>
                                                }
                                            />
                                        </ListItem>
                                    </Zoom>
                                ))}
                            </List>

                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mt: 2 }}>
                                <Typography variant="h5" sx={{ fontWeight: 700 }}>
                                    Subtotal:
                                </Typography>
                                <Typography variant="h4" sx={{ fontWeight: 800, color: theme.palette.success.main }}>
                                    ${subtotal.toFixed(2)}
                                </Typography>
                            </Box>
                        </>
                    )}

                    <Box sx={{ display: 'flex', gap: 2, mt: 3, flexWrap: 'wrap' }}>
                        <Button
                            variant="contained"
                            color="success"
                            onClick={confirmarVenta}
                            disabled={itemsSeleccionados.length === 0}
                            startIcon={<CheckCircle />}
                            sx={{
                                flex: 1,
                                borderRadius: 2,
                                py: 1.5,
                                fontWeight: 600,
                                textTransform: 'none',
                                '&:hover': {
                                    transform: 'scale(1.02)',
                                    boxShadow: '0 8px 25px rgba(0,0,0,0.15)',
                                },
                            }}
                        >
                            Confirmar Venta
                        </Button>
                        <Button
                            variant="contained"
                            color="primary"
                            onClick={imprimirTicket}
                            disabled={itemsSeleccionados.length === 0}
                            startIcon={<Print />}
                            sx={{
                                flex: 1,
                                borderRadius: 2,
                                py: 1.5,
                                fontWeight: 600,
                                textTransform: 'none',
                                '&:hover': {
                                    transform: 'scale(1.02)',
                                    boxShadow: '0 8px 25px rgba(0,0,0,0.15)',
                                },
                            }}
                        >
                            Imprimir Ticket
                        </Button>
                    </Box>
                </Paper>
            </Box>

            {/* ===== SNACKBAR ===== */}
            <Snackbar
                open={snackbarOpen}
                autoHideDuration={4000}
                onClose={() => setSnackbarOpen(false)}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
            >
                <Paper
                    sx={{
                        p: 2,
                        borderRadius: 3,
                        background:
                            snackbarSeverity === 'success'
                                ? `linear-gradient(135deg, ${theme.palette.success.main} 0%, ${theme.palette.success.dark} 100%)`
                                : snackbarSeverity === 'error'
                                    ? `linear-gradient(135deg, ${theme.palette.error.main} 0%, ${theme.palette.error.dark} 100%)`
                                    : `linear-gradient(135deg, ${theme.palette.info.main} 0%, ${theme.palette.info.dark} 100%)`,
                        color: 'white',
                        fontWeight: 600,
                        boxShadow: '0 8px 32px rgba(0,0,0,0.2)',
                        display: 'flex',
                        alignItems: 'center',
                        gap: 1.5,
                        minWidth: 250,
                    }}
                >
                    {snackbarSeverity === 'success' && <CheckCircle />}
                    {snackbarSeverity === 'error' && '⚠️'}
                    {snackbarSeverity === 'info' && 'ℹ️'}
                    {mensaje}
                </Paper>
            </Snackbar>

            {/* ===== BOTÓN VOLVER ===== */}
            <Button
                variant="contained"
                color="warning"
                onClick={() => navigate(-1)}
                startIcon={<ArrowBack />}
                sx={{
                    position: 'fixed',
                    bottom: 24,
                    right: 24,
                    borderRadius: 3,
                    px: 3,
                    py: 1.5,
                    fontWeight: 600,
                    textTransform: 'none',
                    boxShadow: '0 8px 25px rgba(255,152,0,0.3)',
                    '&:hover': {
                        transform: 'scale(1.05)',
                        boxShadow: '0 12px 35px rgba(255,152,0,0.4)',
                    },
                }}
            >
                Volver
            </Button>
        </Container>
    );
}

export default Ventas;