import React, { useState } from 'react';
import {
  Box,
  Typography,
  Container,
  Button,
  TextField,
  Snackbar,
  Grid,
  Avatar,
  Paper,
  Card,
  CardContent,
  alpha,
  useTheme,
  Fade,
  Grow,
  Divider,
  Stack,
  IconButton,
} from '@mui/material';
import {
  Login,
  Logout,
  Storefront,
  BarChart,
  Inventory,
  Person,
  Lock,
  VerifiedUser,
  Home,
} from '@mui/icons-material';
import Stock from './Stock';
import { useNavigate } from 'react-router-dom';
import foto from './IMG_20221031_211846.jpg';
import lumarfoto from './lumar.png';

function App() {
  const theme = useTheme();
  const navigate = useNavigate();

  const [usuario, setUsuario] = useState('');
  const [contraseña, setContraseña] = useState('');
  const [usuarioLogueado, setUsuarioLogueado] = useState(false);
  const [mensaje, setMensaje] = useState('');
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarSeverity, setSnackbarSeverity] = useState('success');
  const [cargando, setCargando] = useState(false);
  const [mostrarStock, setMostrarStock] = useState(false);

  const mensajesBienvenida = [
    '🌟 ¡Bienvenido de vuelta, jefe!',
    '☕ ¿Ya tomaste tu café hoy?',
    '📈 Las ventas te esperan.',
    '💪 ¡A darle con todo hoy!',
    '🧘 Respira hondo y a vender.',
    '🎯 Hoy es un gran día para vender.',
    '🚀 ¡A despegar con las ventas!',
    '💎 Tú eres la clave del éxito.',
  ];

  const obtenerMensajeAleatorio = () => {
    const indiceAleatorio = Math.floor(Math.random() * mensajesBienvenida.length);
    return mensajesBienvenida[indiceAleatorio];
  };

  const mostrarSnackbar = (mensaje, severity = 'success') => {
    setMensaje(mensaje);
    setSnackbarSeverity(severity);
    setSnackbarOpen(true);
  };

  const handleLogin = () => {
    setCargando(true);
    setTimeout(() => {
      if (usuario === 'ruben' && contraseña === 'ñandu1234') {
        setUsuarioLogueado(true);
        mostrarSnackbar(obtenerMensajeAleatorio(), 'success');
      } else {
        mostrarSnackbar('❌ Usuario o contraseña incorrectos', 'error');
      }
      setCargando(false);
    }, 800);
  };

  const handleLogout = () => {
    setUsuarioLogueado(false);
    setUsuario('');
    setContraseña('');
    setMostrarStock(false);
    mostrarSnackbar('👋 Sesión cerrada correctamente', 'info');
  };

  const goToEstadisticas = () => {
    navigate('/Estadisticas');
  };

  const goToVentas = () => {
    navigate('/Ventas');
  };

  const handleKeyDown = (event) => {
    if (event.key === 'Enter' && !cargando) {
      handleLogin();
    }
  };

  return (
    <Box
      sx={{
        minHeight: '100vh',
        background: `linear-gradient(135deg, 
                    ${alpha(theme.palette.primary.main, 0.05)} 0%,
                    ${alpha(theme.palette.secondary.main, 0.05)} 50%,
                    ${alpha(theme.palette.success.main, 0.02)} 100%
                )`,
      }}
    >
      <Container maxWidth="lg" sx={{ py: 4, minHeight: '100vh' }}>
        <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>

          {/* Logo */}
          <Box
            sx={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: 2,
              mb: 4,
              position: 'relative',
              '&::after': {
                content: '""',
                position: 'absolute',
                bottom: -10,
                left: '50%',
                transform: 'translateX(-50%)',
                width: 80,
                height: 3,
                borderRadius: 2,
                background: `linear-gradient(90deg, ${alpha(theme.palette.primary.main, 0.3)}, ${theme.palette.primary.main}, ${alpha(theme.palette.primary.main, 0.3)})`,
              },
            }}
          >
            <Box
              component="img"
              src={lumarfoto}
              alt="Lumar Logo"
              sx={{
                width: 80,
                height: 80,
                borderRadius: '50%',
                objectFit: 'contain',
                boxShadow: '0 8px 32px rgba(0,0,0,0.1)',
                transition: 'transform 0.3s ease',
                '&:hover': {
                  transform: 'rotate(-5deg) scale(1.05)',
                },
              }}
            />
            <Box>
              <Typography
                variant="h3"
                sx={{
                  fontWeight: 800,
                  background: `linear-gradient(135deg, ${theme.palette.primary.main} 0%, ${theme.palette.secondary.main} 100%)`,
                  WebkitBackgroundClip: 'text',
                  WebkitTextFillColor: 'transparent',
                  letterSpacing: -1,
                }}
              >
                Lumar
              </Typography>
              <Typography variant="subtitle1" color="textSecondary" sx={{ fontWeight: 500 }}>
                Sistema de Gestión de Ventas
              </Typography>
            </Box>
          </Box>

          <Grid container spacing={4} justifyContent="center" sx={{ mt: 2 }}>

            {/* Login Card */}
            <Grid item xs={12} md={6} lg={5}>
              <Fade in timeout={500}>
                <Card
                  sx={{
                    borderRadius: 4,
                    p: 4,
                    background: `linear-gradient(135deg, 
                                            ${alpha(theme.palette.background.paper, 0.9)} 0%,
                                            ${alpha(theme.palette.background.default, 0.7)} 100%
                                        )`,
                    backdropFilter: 'blur(20px)',
                    border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                    boxShadow: '0 20px 60px rgba(0,0,0,0.1)',
                    position: 'relative',
                    overflow: 'hidden',
                    '&::before': {
                      content: '""',
                      position: 'absolute',
                      top: -100,
                      right: -100,
                      width: 300,
                      height: 300,
                      background: `radial-gradient(circle, ${alpha(theme.palette.primary.main, 0.05)} 0%, transparent 70%)`,
                      borderRadius: '50%',
                    },
                    '&::after': {
                      content: '""',
                      position: 'absolute',
                      bottom: -150,
                      left: -150,
                      width: 400,
                      height: 400,
                      background: `radial-gradient(circle, ${alpha(theme.palette.secondary.main, 0.05)} 0%, transparent 70%)`,
                      borderRadius: '50%',
                    },
                  }}
                >
                  {!usuarioLogueado ? (
                    <Box>
                      <Typography variant="h5" sx={{ fontWeight: 700, mb: 1 }}>
                        Iniciar Sesión
                      </Typography>
                      <Typography variant="body2" color="textSecondary" sx={{ mb: 3 }}>
                        Ingresa tus credenciales para acceder al sistema
                      </Typography>

                      <TextField
                        fullWidth
                        label="Usuario"
                        variant="outlined"
                        value={usuario}
                        onChange={(e) => setUsuario(e.target.value)}
                        onKeyDown={handleKeyDown}
                        sx={{
                          mb: 2.5,
                          '& .MuiOutlinedInput-root': {
                            borderRadius: 2,
                            background: alpha(theme.palette.background.paper, 0.6),
                          },
                        }}
                        InputProps={{
                          startAdornment: <Person sx={{ mr: 1, color: 'text.secondary' }} />,
                        }}
                      />

                      <TextField
                        fullWidth
                        label="Contraseña"
                        type="password"
                        variant="outlined"
                        value={contraseña}
                        onChange={(e) => setContraseña(e.target.value)}
                        onKeyDown={handleKeyDown}
                        sx={{
                          mb: 3,
                          '& .MuiOutlinedInput-root': {
                            borderRadius: 2,
                            background: alpha(theme.palette.background.paper, 0.6),
                          },
                        }}
                        InputProps={{
                          startAdornment: <Lock sx={{ mr: 1, color: 'text.secondary' }} />,
                        }}
                      />

                      <Button
                        fullWidth
                        onClick={handleLogin}
                        disabled={cargando}
                        variant="contained"
                        startIcon={cargando ? null : <Login />}
                        sx={{
                          borderRadius: 2,
                          py: 1.5,
                          fontWeight: 700,
                          textTransform: 'none',
                          fontSize: '1rem',
                          background: `linear-gradient(135deg, ${theme.palette.primary.main} 0%, ${theme.palette.primary.dark} 100%)`,
                          '&:hover': {
                            transform: 'translateY(-2px)',
                            boxShadow: '0 12px 40px rgba(0,0,0,0.2)',
                          },
                        }}
                      >
                        {cargando ? 'Verificando...' : 'Iniciar Sesión'}
                      </Button>

                      <Box sx={{ display: 'flex', justifyContent: 'center', mt: 2 }}>
                        <Typography variant="caption" color="textSecondary">
                          🔒 Acceso seguro
                        </Typography>
                      </Box>
                    </Box>
                  ) : (
                    <Box>
                      <Box
                        sx={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: 2,
                          mb: 3,
                          p: 2,
                          borderRadius: 3,
                          background: alpha(theme.palette.success.main, 0.05),
                          border: `1px solid ${alpha(theme.palette.success.main, 0.1)}`,
                        }}
                      >
                        <Avatar
                          sx={{
                            width: 56,
                            height: 56,
                            border: `3px solid ${theme.palette.success.main}`,
                          }}
                          alt="Rubén"
                          src={foto}
                        />
                        <Box>
                          <Typography variant="h6" sx={{ fontWeight: 700 }}>
                            ¡Bienvenido, Rubén!
                          </Typography>
                          <Typography variant="body2" sx={{ fontStyle: 'italic', color: 'text.secondary' }}>
                            {mensaje}
                          </Typography>
                        </Box>
                      </Box>

                      <Stack spacing={1.5}>
                        <Button
                          fullWidth
                          onClick={goToVentas}
                          startIcon={<Storefront />}
                          variant="contained"
                          sx={{
                            borderRadius: 2,
                            py: 1.5,
                            fontWeight: 700,
                            textTransform: 'none',
                            background: `linear-gradient(135deg, ${theme.palette.success.main} 0%, ${theme.palette.success.dark} 100%)`,
                            '&:hover': {
                              transform: 'translateY(-2px)',
                            },
                          }}
                        >
                          Ir a Ventas
                        </Button>

                        <Button
                          fullWidth
                          onClick={goToEstadisticas}
                          startIcon={<BarChart />}
                          variant="contained"
                          sx={{
                            borderRadius: 2,
                            py: 1.5,
                            fontWeight: 700,
                            textTransform: 'none',
                            background: `linear-gradient(135deg, ${theme.palette.secondary.main} 0%, ${theme.palette.secondary.dark} 100%)`,
                            '&:hover': {
                              transform: 'translateY(-2px)',
                            },
                          }}
                        >
                          Ir a Estadísticas
                        </Button>

                        <Button
                          fullWidth
                          onClick={() => setMostrarStock(!mostrarStock)}
                          startIcon={<Inventory />}
                          variant="outlined"
                          sx={{
                            borderRadius: 2,
                            py: 1.5,
                            fontWeight: 600,
                            textTransform: 'none',
                            background: alpha(theme.palette.background.paper, 0.6),
                            backdropFilter: 'blur(10px)',
                            '&:hover': {
                              transform: 'translateY(-2px)',
                              boxShadow: '0 8px 30px rgba(0,0,0,0.1)',
                            },
                          }}
                        >
                          {mostrarStock ? 'Ocultar Stock' : 'Ver Stock'}
                        </Button>

                        <Divider sx={{ my: 1 }} />

                        <Button
                          fullWidth
                          onClick={handleLogout}
                          variant="outlined"
                          color="warning"
                          startIcon={<Logout />}
                          sx={{
                            borderRadius: 2,
                            py: 1.5,
                            fontWeight: 600,
                            textTransform: 'none',
                          }}
                        >
                          Cerrar Sesión
                        </Button>
                      </Stack>
                    </Box>
                  )}
                </Card>
              </Fade>
            </Grid>

            {/* Info Panel */}
            {!usuarioLogueado && (
              <Grid item xs={12} md={6} lg={5}>
                <Fade in timeout={700}>
                  <Box
                    sx={{
                      display: { xs: 'none', md: 'flex' },
                      flexDirection: 'column',
                      justifyContent: 'center',
                      alignItems: 'center',
                      textAlign: 'center',
                      p: 4,
                      borderRadius: 4,
                      height: '100%',
                      minHeight: 400,
                      background: `linear-gradient(135deg, 
                                                ${alpha(theme.palette.primary.main, 0.03)} 0%,
                                                ${alpha(theme.palette.secondary.main, 0.03)} 100%
                                            )`,
                      border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                    }}
                  >
                    <VerifiedUser sx={{ fontSize: 80, color: 'primary.main', mb: 2, opacity: 0.3 }} />
                    <Typography variant="h5" sx={{ fontWeight: 600, mb: 2 }}>
                      Sistema Seguro
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                      Accede a tu cuenta para gestionar ventas, inventario y estadísticas en tiempo real.
                    </Typography>
                    <Box sx={{ display: 'flex', gap: 1, mt: 3 }}>
                      {['Ventas', 'Stock', 'Estadísticas'].map((item) => (
                        <Box
                          key={item}
                          sx={{
                            px: 2,
                            py: 1,
                            borderRadius: 2,
                            background: alpha(theme.palette.primary.main, 0.08),
                            fontSize: '0.75rem',
                            fontWeight: 600,
                            color: 'primary.main',
                          }}
                        >
                          {item}
                        </Box>
                      ))}
                    </Box>
                  </Box>
                </Fade>
              </Grid>
            )}
          </Grid>

          {/* Stock Component */}
          {usuarioLogueado && mostrarStock && (
            <Grow in timeout={300}>
              <Box sx={{ width: '100%', mt: 4 }}>
                <Paper
                  elevation={0}
                  sx={{
                    p: 3,
                    borderRadius: 4,
                    background: alpha(theme.palette.background.paper, 0.6),
                    border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                  }}
                >
                  <Typography variant="h6" sx={{ fontWeight: 700, mb: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Inventory color="primary" />
                    Gestión de Stock
                  </Typography>
                  <Stock />
                </Paper>
              </Box>
            </Grow>
          )}

          {/* Snackbar */}
          <Snackbar
            open={snackbarOpen}
            autoHideDuration={4000}
            onClose={() => setSnackbarOpen(false)}
            anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
          >
            <Paper
              sx={{
                p: 2,
                borderRadius: 3,
                background:
                  snackbarSeverity === 'success'
                    ? `linear-gradient(135deg, ${theme.palette.success.main} 0%, ${theme.palette.success.dark} 100%)`
                    : snackbarSeverity === 'error'
                      ? `linear-gradient(135deg, ${theme.palette.error.main} 0%, ${theme.palette.error.dark} 100%)`
                      : `linear-gradient(135deg, ${theme.palette.info.main} 0%, ${theme.palette.info.dark} 100%)`,
                color: 'white',
                fontWeight: 500,
                boxShadow: '0 8px 32px rgba(0,0,0,0.15)',
                display: 'flex',
                alignItems: 'center',
                gap: 1.5,
                minWidth: 300,
              }}
            >
              {mensaje}
            </Paper>
          </Snackbar>

          {/* Floating Home Button */}
          {usuarioLogueado && (
            <Button
              variant="contained"
              color="warning"
              onClick={() => navigate('/')}
              startIcon={<Home />}
              sx={{
                position: 'fixed',
                bottom: 24,
                right: 24,
                borderRadius: 3,
                px: 3,
                py: 1.5,
                fontWeight: 600,
                textTransform: 'none',
                boxShadow: '0 8px 32px rgba(255,152,0,0.3)',
                transition: 'all 0.3s ease',
                '&:hover': {
                  transform: 'scale(1.05)',
                  boxShadow: '0 12px 40px rgba(255,152,0,0.4)',
                },
              }}
            >
              Inicio
            </Button>
          )}
        </Box>
      </Container>
    </Box>
  );
}

export default App;